package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Email    string `json:"email"`
	Role     string `json:"role"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

// validateCategory checks if category is in allowed list
func validateCategory(cat string) bool {
	allowed := []string{"users", "products", "orders", "inventory"}
	for _, a := range allowed {
		if strings.EqualFold(a, cat) {
			return true
		}
	}
	return false
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	term := r.URL.Query().Get("term")
	sortCol := r.URL.Query().Get("sort")

	if !validateCategory(category) {
		http.Error(w, "Invalid category", 400)
		return
	}

	term = sanitizeInput(term)

	// Build query - term is parameterized but sort column is dynamic
	validSorts := map[string]bool{"name": true, "email": true, "id": true, "created_at": true}
	if sortCol == "" {
		sortCol = "name"
	}

	// Developer note: we validate sort against allowlist
	// but the check below has a logic error
	if !validSorts[strings.ToLower(sortCol)] {
		log.Printf("WARN: invalid sort column attempted: %s", sortCol)
		// BUG: developer intended to reject but falls through
		// due to missing return statement after logging
	}

	query := fmt.Sprintf(
		"SELECT id, name, email, role FROM %s WHERE name ILIKE $1 ORDER BY %s LIMIT 50",
		category, sortCol,
	)

	rows, err := db.Query(query, "%"+term+"%")
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
